<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Grade to Percentage Calculator</title>
    <style>
        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: #f4f6f9;
            color: #333;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            margin: 0;
            padding: 20px;
        }
        .calculator-card {
            background: #fff;
            padding: 30px;
            border-radius: 12px;
            box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1);
            width: 100%;
            max-width: 480px;
        }
        h2 {
            text-align: center;
            margin-top: 0;
            color: #2c3e50;
        }
        .tabs {
            display: flex;
            justify-content: space-around;
            margin-bottom: 20px;
            border-bottom: 2px solid #ddd;
        }
        .tab-btn {
            background: none;
            border: none;
            padding: 10px 15px;
            font-size: 14px;
            font-weight: 600;
            cursor: pointer;
            color: #7f8c8d;
            border-bottom: 3px solid transparent;
            transition: all 0.3s;
        }
        .tab-btn.active {
            color: #3498db;
            border-bottom-color: #3498db;
        }
        .tab-content {
            display: none;
        }
        .tab-content.active {
            display: block;
        }
        .input-group {
            margin-bottom: 15px;
        }
        label {
            display: block;
            font-weight: 600;
            margin-bottom: 5px;
            color: #34495e;
        }
        input, select {
            width: 100%;
            padding: 10px;
            border: 1px solid #ccc;
            border-radius: 6px;
            box-sizing: border-box;
            font-size: 16px;
        }
        button.calc-btn {
            width: 100%;
            padding: 12px;
            background-color: #3498db;
            color: white;
            border: none;
            border-radius: 6px;
            font-size: 16px;
            font-weight: bold;
            cursor: pointer;
            transition: background 0.2s;
        }
        button.calc-btn:hover {
            background-color: #2980b9;
        }
        .result-box {
            margin-top: 20px;
            padding: 15px;
            background-color: #e8f4fd;
            border-left: 5px solid #3498db;
            border-radius: 4px;
            font-size: 18px;
            font-weight: bold;
            color: #2c3e50;
            text-align: center;
            display: none;
        }
    </style>
</head>
<body>

<div class="calculator-card">
    <h2>Grade Converter</h2>

    <div class="tabs">
        <button class="tab-btn active" onclick="switchTab('score-tab', this)">Score / Points</button>
        <button class="tab-btn" onclick="switchTab('letter-tab', this)">Letter Grade</button>
        <button class="tab-btn" onclick="switchTab('gpa-tab', this)">GPA (4.0)</button>
    </div>

    <!-- Score Tab -->
    <div id="score-tab" class="tab-content active">
        <div class="input-group">
            <label for="earned">Points Earned</label>
            <input type="number" id="earned" placeholder="e.g. 18" step="any">
        </div>
        <div class="input-group">
            <label for="total">Total Possible Points</label>
            <input type="number" id="total" placeholder="e.g. 25" step="any">
        </div>
        <button class="calc-btn" onclick="calculateScore()">Calculate Percentage</button>
        <div id="score-result" class="result-box"></div>
    </div>

    <!-- Letter Grade Tab -->
    <div id="letter-tab" class="tab-content">
        <div class="input-group">
            <label for="letter">Select Letter Grade</label>
            <select id="letter">
                <option value="98">A+ (97% - 100%)</option>
                <option value="95">A (93% - 96%)</option>
                <option value="91">A- (90% - 92%)</option>
                <option value="88">B+ (87% - 89%)</option>
                <option value="85">B (83% - 86%)</option>
                <option value="81">B- (80% - 82%)</option>
                <option value="78">C+ (77% - 79%)</option>
                <option value="75">C (73% - 76%)</option>
                <option value="71">C- (70% - 72%)</option>
                <option value="68">D+ (67% - 69%)</option>
                <option value="65">D (63% - 66%)</option>
                <option value="61">D- (60% - 62%)</option>
                <option value="50">F (Below 60%)</option>
            </select>
        </div>
        <button class="calc-btn" onclick="calculateLetter()">Convert to Percentage</button>
        <div id="letter-result" class="result-box"></div>
    </div>

    <!-- GPA Tab -->
    <div id="gpa-tab" class="tab-content">
        <div class="input-group">
            <label for="gpa">Enter GPA (out of 4.0)</label>
            <input type="number" id="gpa" placeholder="e.g. 3.7" min="0" max="4.0" step="0.01">
        </div>
        <button class="calc-btn" onclick="calculateGPA()">Convert to Percentage</button>
        <div id="gpa-result" class="result-box"></div>
    </div>
</div>

<script>
    function switchTab(tabId, btn) {
        const contents = document.querySelectorAll('.tab-content');
        contents.forEach(content => content.classList.remove('active'));

        const buttons = document.querySelectorAll('.tab-btn');
        buttons.forEach(b => b.classList.remove('active'));

        document.getElementById(tabId).classList.add('active');
        btn.classList.add('active');
    }

    function calculateScore() {
        const earned = parseFloat(document.getElementById('earned').value);
        const total = parseFloat(document.getElementById('total').value);
        const resultDiv = document.getElementById('score-result');

        if (isNaN(earned) || isNaN(total) || total <= 0) {
            resultDiv.style.display = 'block';
            resultDiv.style.backgroundColor = '#fde8e8';
            resultDiv.style.borderLeftColor = '#f53b57';
            resultDiv.style.color = '#c0392b';
            resultDiv.innerText = "Please enter valid points.";
            return;
        }

        const percentage = ((earned / total) * 100).toFixed(2);
        resultDiv.style.display = 'block';
        resultDiv.style.backgroundColor = '#e8f4fd';
        resultDiv.style.borderLeftColor = '#3498db';
        resultDiv.style.color = '#2c3e50';
        resultDiv.innerText = `${earned} / ${total} = ${percentage}%`;
    }

    function calculateLetter() {
        const select = document.getElementById('letter');
        const percentage = select.value;
        const text = select.options[select.selectedIndex].text;
        const resultDiv = document.getElementById('letter-result');

        resultDiv.style.display = 'block';
        resultDiv.style.backgroundColor = '#e8f4fd';
        resultDiv.style.borderLeftColor = '#3498db';
        resultDiv.style.color = '#2c3e50';
        resultDiv.innerText = `Typical Range for ${text.split(' ')[0]} is approx. ${percentage}%`;
    }

    function calculateGPA() {
        const gpa = parseFloat(document.getElementById('gpa').value);
        const resultDiv = document.getElementById('gpa-result');

        if (isNaN(gpa) || gpa < 0 || gpa > 4.0) {
            resultDiv.style.display = 'block';
            resultDiv.style.backgroundColor = '#fde8e8';
            resultDiv.style.borderLeftColor = '#f53b57';
            resultDiv.style.color = '#c0392b';
            resultDiv.innerText = "Please enter a valid GPA between 0.0 and 4.0.";
            return;
        }

        const percentageLinear = (gpa * 25).toFixed(1);
        const percentageStandard = ((gpa * 20) + 20).toFixed(1);

        resultDiv.style.display = 'block';
        resultDiv.style.backgroundColor = '#e8f4fd';
        resultDiv.style.borderLeftColor = '#3498db';
        resultDiv.style.color = '#2c3e50';
        resultDiv.innerHTML = `
            <strong>Strict Ratio:</strong> ${percentageLinear}%<br>
            <span style="font-size:13px; font-weight:normal; color:#555;">(GPA × 25)</span><br>
            <strong style="margin-top:5px; display:inline-block;">Common HS Scale:</strong> ${percentageStandard}%<br>
            <span style="font-size:13px; font-weight:normal; color:#555;">((GPA × 20) + 20)</span>
        `;
    }
</script>

</body>
</html>
```

